export function getCompanyBySlug(slug: string): CompanyInfo | undefined {
  const norm = slug.toLowerCase();
  return COMPANIES.find((c) => c.slug.toLowerCase() === norm);
}

export function getCompanyProblems(slug: string): CompanyProblem[] {
  if (typeof window === 'undefined') {
    try {
      const fs = require('fs');
      const path = require('path');
      const filePath = path.join(process.cwd(), 'data', 'companies', );
      if (fs.existsSync(filePath)) {
        return JSON.parse(fs.readFileSync(filePath, 'utf-8'));
      }
    } catch {}
  }
  return [];
}

export function toPracticeProblem(cp: CompanyProblem, companyName: string): PracticeProblem {
  return {
    id: cp.id,
    slug: cp.slug,
    title: cp.title,
    difficulty: cp.difficulty,
    category: cp.topics[0] || 'Algorithms',
    frequency: cp.frequency,
    leetcodeUrl: cp.leetcodeUrl,
    topics: cp.topics,
    companies: [companyName],
    description: `Problem frequently asked at ${companyName}. Solve and test your solution.`,
    examples: [],
    constraints: [],
    starterCodes: {
      Java: `class Solution {\n    // Write code here\n}`,
      Python: `class Solution:\n    # Write code here\n    pass`,
      'C++': `class Solution {\npublic:\n    // Write code here\n};`,
      JavaScript: '// Write code here',
      TypeScript: '// Write code here',
    },
  };
}

export const COMPANY_PROBLEMS: PracticeProblem[] = [];
